begin;
select no_plan();
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('b1100000-0000-0000-0000-000000000001','authenticated','authenticated','phase11-a@example.test','',now(),'{}','{"name":"Commission A","company_name":"Commission A"}',now(),now()),
('b1100000-0000-0000-0000-000000000002','authenticated','authenticated','phase11-b@example.test','',now(),'{}','{"name":"Commission B","company_name":"Commission B"}',now(),now());
select set_config('request.jwt.claims','{"sub":"b1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select set_config('p11.company',private.current_company_id(),true);
select set_config('p11.seller',(select id from public.profiles where auth_user_id=auth.uid()),true);
create function pg_temp.p11_rule(p jsonb) returns jsonb language sql as $$select public.commission_command(gen_random_uuid(),'rule_save',jsonb_build_object('revision',coalesce((select revision from public.commission_rules where company_id=private.current_company_id() and seller_profile_id is null),0),'active',true,'kind','percent','amount',10,'base','net_sale','policy','fully_paid','exclude_shipping',true,'deduct_discount',true,'origins',jsonb_build_array('manual','quote','pos','store'))||p)$$;
create function pg_temp.p11_action(a text,p jsonb default '{}') returns jsonb language sql as $$select public.commission_command(gen_random_uuid(),a,jsonb_build_object('period_id',current_setting('p11.period'),'revision',(select revision from public.commission_periods where id=current_setting('p11.period')::uuid),'seller_id',current_setting('p11.seller'))||p)$$;
grant execute on function pg_temp.p11_rule(jsonb),pg_temp.p11_action(text,jsonb) to authenticated;
set local role authenticated;
select ok(not has_function_privilege('anon','public.commission_source(uuid,date,date,text,text)','execute'),'anon cannot read commissions');
select ok(not has_function_privilege('anon','public.commission_command(uuid,text,jsonb)','execute'),'anon cannot mutate commissions');
select ok(not has_table_privilege('authenticated','public.commission_entries','insert'),'browser cannot forge snapshots');
select ok(not has_function_privilege('authenticated','private.commission_calculate(text,date,date)','execute'),'private canonical engine not exposed');
select is(jsonb_array_length(public.commission_source(null,'2026-10-01','2026-10-31')->'rows'),0,'empty source honest');
select set_config('p11.bank',public.finance_command(gen_random_uuid(),'account_create','{"name":"Synthetic commission bank","kind":"bank","amount":1000}')#>>'{account,id}',true);
select pg_temp.p11_rule('{}');
select public.commission_command(gen_random_uuid(),'rule_save',jsonb_build_object('seller_id',current_setting('p11.seller'),'active',true,'use_default',true,'revision',0));
reset role;
insert into public.orders(id,company_id,customer_name,number,status,total_amount,paid_amount,shipping_cost,additional_services,created_at) values
('p11-good',current_setting('p11.company'),'Synthetic customer','PED-1101','producao',110,110,10,'[{"total_price":30}]','2026-10-02T12:00Z'),
('p11-partial',current_setting('p11.company'),'Synthetic partial','PED-1102','producao',100,100,0,'[]','2026-10-03T12:00Z'),
('p11-cancelled',current_setting('p11.company'),'Synthetic cancelled','PED-1103','cancelado',100,100,0,'[]','2026-10-04T12:00Z'),
('p11-unassigned',current_setting('p11.company'),'No attribution','PED-1104','producao',100,100,0,'[]','2026-10-05T12:00Z'),
('p11-round',current_setting('p11.company'),'Rounding','PED-1105','producao',100.05,0,0,'[]','2026-09-02T12:00Z');
insert into public.order_items(order_id,product_name,quantity,unit_price,total_price) values('p11-good','Synthetic product',1,120,120),('p11-partial','Synthetic product',1,100,100),('p11-round','Rounding',1,100.05,100.05);
insert into public.customers(id,company_id,name,document) values('p11-customer',current_setting('p11.company'),'Synthetic customer','');
update public.orders set customer_id='p11-customer' where company_id=current_setting('p11.company');
insert into public.financial_transactions(id,company_id,account_id,order_id,order_number,type,category,amount,description,payment_method,status,due_date,paid_at,source) values
('p11-receipt',current_setting('p11.company'),current_setting('p11.bank')::uuid,'p11-good','PED-1101','receita','Vendas',110,'Synthetic sale','pix','pago','2026-10-02','2026-10-02T12:00Z','order_payment'),
('p11-partial-receipt',current_setting('p11.company'),current_setting('p11.bank')::uuid,null,'ORD-1102','receita','Vendas',50,'Synthetic partial','pix','pago','2026-10-03','2026-10-03T12:00Z','order_payment');
set local role authenticated;
select public.commission_command(gen_random_uuid(),'assign',jsonb_build_object('order_id','p11-good','seller_id',current_setting('p11.seller'),'origin','manual','revision',0));
select public.commission_command(gen_random_uuid(),'assign',jsonb_build_object('order_id','p11-partial','seller_id',current_setting('p11.seller'),'origin','quote','revision',0));
select public.commission_command(gen_random_uuid(),'assign',jsonb_build_object('order_id','p11-cancelled','seller_id',current_setting('p11.seller'),'origin','pos','revision',0));
select public.commission_command(gen_random_uuid(),'assign',jsonb_build_object('order_id','p11-round','seller_id',current_setting('p11.seller'),'origin','manual','revision',0));
select is(jsonb_array_length(public.commission_source(null,'2026-10-01','2026-10-31')->'rows'),1,'cancelled, partial and unassigned excluded; paid cache not proof');
select is((public.commission_source(null,'2026-10-01','2026-10-31')#>>'{rows,0,base}')::numeric,100::numeric,'discount already in persisted total, shipping excluded');
select is((public.commission_source(null,'2026-10-01','2026-10-31')#>>'{summary,estimated}')::numeric,10::numeric,'canonical percent on net sale');
select pg_temp.p11_rule('{"policy":"approved_sale"}');
select is(jsonb_array_length(public.commission_source(null,'2026-10-01','2026-10-31')->'rows'),2,'approved policy includes partially paid sale explicitly');
select is((public.commission_source(null,'2026-09-01','2026-09-30')#>>'{rows,0,amount}')::numeric,10.01::numeric,'numeric rounding is canonical half up');
select pg_temp.p11_rule('{"base":"net_products"}');
select is((public.commission_source(null,'2026-10-01','2026-10-31')#>>'{rows,0,base}')::numeric,80::numeric,'product-only prorates net total against products/services');
select pg_temp.p11_rule('{"base":"net_products","exclude_shipping":false}');
select is((public.commission_source(null,'2026-10-01','2026-10-31')#>>'{rows,0,amount}')::numeric,9::numeric,'shipping inclusion explicit, not default');
select pg_temp.p11_rule('{"base":"net_products","deduct_discount":false}');
select is((public.commission_source(null,'2026-10-01','2026-10-31')#>>'{rows,0,base}')::numeric,120::numeric,'gross base only when discount deduction explicitly disabled');
select pg_temp.p11_rule('{"kind":"fixed","amount":7.13}');
select is((public.commission_source(null,'2026-10-01','2026-10-31')#>>'{rows,0,amount}')::numeric,7.13::numeric,'fixed amount per eligible Order');
select pg_temp.p11_rule('{"origins":["store"]}');
select is(jsonb_array_length(public.commission_source(null,'2026-10-01','2026-10-31')->'rows'),0,'origin allowlist enforced');
select pg_temp.p11_rule('{}');
select public.commission_command(gen_random_uuid(),'rule_save',jsonb_build_object('seller_id',current_setting('p11.seller'),'active',true,'use_default',false,'kind','percent','amount',3,'revision',(select revision from public.commission_rules where seller_profile_id=current_setting('p11.seller'))));
select is((public.commission_source(null,'2026-10-01','2026-10-31')#>>'{rows,0,amount}')::numeric,3::numeric,'seller override has priority over default');
select public.commission_command(gen_random_uuid(),'rule_save',jsonb_build_object('seller_id',current_setting('p11.seller'),'active',true,'use_default',true,'revision',(select revision from public.commission_rules where seller_profile_id=current_setting('p11.seller'))));
select set_config('p11.period',public.commission_command(gen_random_uuid(),'period_create','{"name":"October synthetic","starts_on":"2026-10-01","ends_on":"2026-10-31"}')->>'id',true);
select throws_ok($$select public.commission_command(gen_random_uuid(),'period_create','{"name":"Overlap","starts_on":"2026-10-20","ends_on":"2026-11-01"}')$$,'22023','Períodos não podem se sobrepor','custom windows cannot duplicate sales');
select set_config('p11.close_payload',jsonb_build_object('period_id',current_setting('p11.period'),'revision',1)::text,true);
select public.commission_command('b1100000-0000-0000-0000-000000000010','close',current_setting('p11.close_payload')::jsonb);
select public.commission_command('b1100000-0000-0000-0000-000000000010','close',current_setting('p11.close_payload')::jsonb);
select is((select count(*)::integer from public.commission_entries),1,'close retry snapshots once');
select is((select count(*)::integer from public.audit_logs where action='commission.period_closed'),1,'close retry audits once');
select pg_temp.p11_rule('{"amount":20}');
select is((public.commission_source(current_setting('p11.period')::uuid,'2026-10-01','2026-10-31')#>>'{rows,0,amount}')::numeric,10::numeric,'future rule does not change closed snapshot');
select throws_ok($$select pg_temp.p11_action('close')$$,'22023','Período precisa estar aberto','different key cannot close twice');
select is((public.save_order_with_items_and_production((select to_jsonb(o)||'{"notes":"RPC note only"}'::jsonb from public.orders o where id='p11-good'),(select jsonb_agg(to_jsonb(i)) from public.order_items i where order_id='p11-good'),(select updated_at from public.orders where id='p11-good'))->>'result_status'),'UPDATED','real aggregate Order RPC accepts notes-only edit after commission close');
select is((select notes from public.orders where id='p11-good'),'RPC note only','canonical Order edit persisted');
reset role;
select lives_ok($$update public.orders set notes='Only a note',deadline='2026-11-01' where id='p11-good'$$,'non monetary Order edit remains available');
select throws_ok($$update public.orders set total_amount=200 where id='p11-good'$$,'22023','Reabra o período de comissão antes de alterar valores da venda','closed sale monetary edit controlled');
-- Aggregate save may replace identical items; a deferred guard checks only final totals.
delete from public.order_items where order_id='p11-good';
insert into public.order_items(order_id,product_name,quantity,unit_price,total_price) values('p11-good','Synthetic product',1,120,120);
set constraints commission_item_guard immediate;
select pass('replacement of economically identical items succeeds');
select throws_ok($$update public.order_items set total_price=999 where order_id='p11-good';set constraints commission_item_guard immediate$$,'22023','Reabra o período de comissão antes de alterar valores dos itens','deferred guard rejects changed final monetary aggregate');
set constraints commission_item_guard deferred;
set local role authenticated;
select pg_temp.p11_action('adjust','{"amount":5,"reason":"Synthetic bonus"}');
select pg_temp.p11_action('adjust','{"amount":-2,"reason":"Synthetic correction"}');
select is((public.commission_source(current_setting('p11.period')::uuid,'2026-10-01','2026-10-31')#>>'{summary,estimated}')::numeric,13::numeric,'positive and negative adjustments append');
select pg_temp.p11_action('approve');
reset role;
create function pg_temp.p11_fail_cash() returns trigger language plpgsql as $$begin if new.source='commission' then raise exception 'Injected commission failure';end if;return new;end$$;
create trigger p11_fail_cash before insert on public.financial_transactions for each row execute function pg_temp.p11_fail_cash();
set local role authenticated;
select throws_ok($$select public.commission_command('b1100000-0000-0000-0000-000000000099','pay',jsonb_build_object('period_id',current_setting('p11.period'),'revision',(select revision from public.commission_periods where id=current_setting('p11.period')::uuid),'seller_id',current_setting('p11.seller'),'account_id',current_setting('p11.bank'),'date','2026-10-20','method','pix'))$$,'P0001','Injected commission failure','cash failure rolls back settlement atomically');
select is((select count(*)::integer from public.commission_payments),0,'failed cash leaves no commission payment');
select is((select count(*)::integer from public.financial_transactions where source='commission'),0,'failed cash leaves no ledger expense');
reset role;
select is((select count(*)::integer from private.commission_commands where operation_id='b1100000-0000-0000-0000-000000000099'),0,'failed command has no success receipt');
select is((select count(*)::integer from public.audit_logs where metadata->>'operation_id'='b1100000-0000-0000-0000-000000000099'),0,'failed command has no success audit');
drop trigger p11_fail_cash on public.financial_transactions;
set local role authenticated;
select set_config('p11.pay_payload',jsonb_build_object('period_id',current_setting('p11.period'),'revision',(select revision from public.commission_periods where id=current_setting('p11.period')::uuid),'seller_id',current_setting('p11.seller'),'account_id',current_setting('p11.bank'),'date','2026-10-20','method','pix')::text,true);
select public.commission_command('b1100000-0000-0000-0000-000000000011','pay',current_setting('p11.pay_payload')::jsonb);
select public.commission_command('b1100000-0000-0000-0000-000000000011','pay',current_setting('p11.pay_payload')::jsonb);
select is((select count(*)::integer from public.commission_payments),1,'pay retry creates one settlement');
select is((select count(*)::integer from public.financial_transactions where source='commission'),1,'one settlement one cash expense');
select is((select amount from public.financial_transactions where source='commission'),13::numeric,'expense matches seller amount including adjustments');
select is((select status from public.commission_periods where id=current_setting('p11.period')::uuid),'paid','fully settled period paid');
select is((public.reports_source('finance','2026-10-01','2026-10-31','{"origin":"commission"}')#>>'{summary,expense}')::numeric,13::numeric,'canonical DRE includes commission cash expense');
select throws_ok($$select public.finance_command(gen_random_uuid(),'payable_reverse',(select jsonb_build_object('id',id,'updated_at',updated_at) from public.financial_transactions where source='commission'))$$,'42501','Use Comissões para reverter este pagamento','direct finance RPC cannot desynchronize commissions');
select throws_ok($$select pg_temp.p11_action('reopen','{"reason":"Attempt while paid"}')$$,'22023','Reabertura exige motivo e reversão dos pagamentos','paid period cannot reopen');
reset role;
update public.orders set status='cancelado' where id='p11-good';
set local role authenticated;
select is((select amount from public.commission_entries where order_id='p11-good'),10::numeric,'cancel preserves frozen amount');
select is((select amount from public.commission_adjustments where automatic),(-10)::numeric,'cancel adds compensating adjustment');
select is((public.commission_source(current_setting('p11.period')::uuid,'2026-10-01','2026-10-31')#>>'{summary,recovery}')::numeric,10::numeric,'paid cancellation exposes recoverable amount');
select is((select status from public.commission_periods where id=current_setting('p11.period')::uuid),'review_required','cancelled paid sale requires review');
select is((select count(*)::integer from public.financial_transactions where reversal_of is not null),0,'cancellation never reverses bank automatically');
select pg_temp.p11_action('reverse',jsonb_build_object('payment_id',(select id from public.commission_payments),'date','2026-10-21','reason','Synthetic reversal'));
select is((select count(*)::integer from public.financial_transactions where reversal_of is not null),1,'controlled reversal appends compensation');
select is((select sum(case when type='receita' then amount else -amount end) from public.financial_transactions where source='commission' or reversal_of=(select transaction_id from public.commission_payments)),0::numeric,'reversal neutralizes commission cash exactly');
select is((public.reports_source('finance','2026-10-01','2026-10-31','{"origin":"commission"}')#>>'{summary,expense}')::numeric,0::numeric,'canonical DRE nets expense and reversal without a second ledger');
select pg_temp.p11_action('reopen','{"reason":"New calculation cycle"}');
select is((select count(*)::integer from public.commission_entries where voided),1,'reopen preserves old snapshot as history');
select is(jsonb_array_length(public.commission_source(current_setting('p11.period')::uuid,'2026-10-01','2026-10-31')->'historyPayments'),1,'reopen preserves payment/reversal visibility');
select is(jsonb_array_length(public.commission_source(current_setting('p11.period')::uuid,'2026-10-01','2026-10-31')->'historyAdjustments'),3,'reopen preserves adjustment history');
reset role;
insert into public.financial_transactions(id,company_id,account_id,order_number,type,category,amount,payment_method,status,due_date,paid_at,source) values('p11-partial-last',current_setting('p11.company'),current_setting('p11.bank')::uuid,'PED-1102','receita','Vendas',50,'pix','pago','2026-10-10','2026-10-10T12:00Z','order_payment');
set local role authenticated;
select pg_temp.p11_action('close');
select is((select amount from public.commission_entries where not voided),20::numeric,'new cycle uses new rule and newly paid sale');
reset role;
insert into public.financial_transactions(id,company_id,account_id,type,category,amount,payment_method,status,due_date,paid_at,source,reversal_of) values('p11-refund',current_setting('p11.company'),current_setting('p11.bank')::uuid,'despesa','Vendas',50,'pix','pago','2026-10-11','2026-10-11T12:00Z','reversal','p11-partial-last');
select set_config('printflow.finance_command','on',true);
update public.financial_transactions set reversed_at=now() where id='p11-partial-last';
select set_config('printflow.finance_command','off',true);
set local role authenticated;
select is((select amount from public.commission_adjustments where automatic and generation=2),(-20)::numeric,'legacy number-only refund invalidates once');
select is((public.commission_source(current_setting('p11.period')::uuid,'2026-10-01','2026-10-31')#>>'{summary,estimated}')::numeric,0::numeric,'invalidated commission has zero valid balance');
select throws_ok($$select public.commission_command('b1100000-0000-0000-0000-000000000011','pay','{}')$$,'22023','Operation key reused','receipt cannot be reused with changed payload');
reset role;
select set_config('request.jwt.claims','{"sub":"b1100000-0000-0000-0000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::integer from public.commission_entries),0,'tenant B cannot read A snapshots');
select throws_ok($$select public.commission_source(current_setting('p11.period')::uuid,'2026-10-01','2026-10-31')$$,'P0002','Período indisponível','cross tenant period read denied');
select throws_ok($$select pg_temp.p11_action('approve')$$,'P0002','Período indisponível','cross tenant mutation denied');
reset role;
select set_config('request.jwt.claims','{"sub":"b1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
insert into public.role_permissions(company_id,path,roles) values(current_setting('p11.company'),'/financial',array[]::text[]) on conflict(company_id,path) do update set roles=excluded.roles;
set local role authenticated;
select is((select count(*)::integer from public.commission_rules),0,'explicit finance denial also applies to admin');
select throws_ok($$select public.commission_source()$$,'42501','Commission access denied','source enforces financial permission');
select throws_ok($$select pg_temp.p11_rule('{}')$$,'42501','Commission access denied','write enforces financial permission');
reset role;
select set_config('request.jwt.claims','{}',true);
select lives_ok($$select private.commission_audit(current_setting('p11.company'),'commission.maintenance_probe','probe','{}','{}')$$,'maintenance without JWT follows existing silent audit governance');
select is((select count(*)::integer from public.audit_logs where action='commission.maintenance_probe'),0,'maintenance does not invent human or system actor');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select lives_ok($$select private.commission_audit(current_setting('p11.company'),'commission.system_probe','probe','{}','{}')$$,'service audit satisfies actor identity constraint');
select is((select actor_name||'/'||actor_role from public.audit_logs where action='commission.system_probe'),'SYSTEM/system','service actor uses canonical SYSTEM identity');
select set_config('request.jwt.claims','{"sub":"b1100000-0000-0000-0000-000000000099","role":"authenticated"}',true);
select throws_ok($$select private.commission_audit(current_setting('p11.company'),'commission.invalid_actor','probe','{}','{}')$$,'42501','Commission audit actor not authorized','authenticated audit cannot fabricate an absent profile');
select * from finish();
rollback;
